public class ElevatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("IDLE + up", Elevator.State.MOVING_UP, Elevator.next(Elevator.State.IDLE, "up"));
        check("IDLE + down", Elevator.State.MOVING_DOWN, Elevator.next(Elevator.State.IDLE, "down"));
        check("MOVING_UP + stop", Elevator.State.IDLE, Elevator.next(Elevator.State.MOVING_UP, "stop"));
        check("MOVING_DOWN + stop", Elevator.State.IDLE, Elevator.next(Elevator.State.MOVING_DOWN, "stop"));
        check("IDLE + open", Elevator.State.DOORS_OPEN, Elevator.next(Elevator.State.IDLE, "open"));
        check("DOORS_OPEN + close", Elevator.State.IDLE, Elevator.next(Elevator.State.DOORS_OPEN, "close"));
        check("MOVING_UP + open is ignored", Elevator.State.MOVING_UP,
                Elevator.next(Elevator.State.MOVING_UP, "open"));
        check("IDLE + unknown command", Elevator.State.IDLE, Elevator.next(Elevator.State.IDLE, "jump"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

