public class Elevator {

    public enum State { IDLE, MOVING_UP, MOVING_DOWN, DOORS_OPEN }

    public static State next(State current, String command) {
        switch (command) {
            case "up":
                return current == State.IDLE ? State.MOVING_UP : current;
            case "down":
                return current == State.IDLE ? State.MOVING_DOWN : current;
            case "stop":
                return (current == State.MOVING_UP || current == State.MOVING_DOWN)
                        ? State.IDLE : current;
            case "open":
                return current == State.IDLE ? State.DOORS_OPEN : current;
            case "close":
                return current == State.DOORS_OPEN ? State.IDLE : current;
            default:
                return current;
        }
    }
}
